'use strict';
const people=document.querySelector('#people');
const hours=document.querySelector('#hours');
function calculate(){const p=Number(people.value),h=Number(hours.value),total=p*h*20;document.querySelector('#people-value').value=p;document.querySelector('#hours-value').value=h;document.querySelector('#capacity').textContent=total.toLocaleString('en');document.querySelector('#annual').textContent=(total*12).toLocaleString('en');}
people.addEventListener('input',calculate);hours.addEventListener('input',calculate);
document.querySelectorAll('[data-service]').forEach(link=>link.addEventListener('click',()=>{document.querySelector('#interest').value=link.dataset.service;}));
document.querySelector('#draft-button').addEventListener('click',()=>{const idea=document.querySelector('#brief').value.trim();document.querySelector('#prepared-brief').value=`Project interest: ${document.querySelector('#interest').value}\n\nWhat we would like to improve:\n${idea||'We would like help identifying a practical opportunity for our business.'}\n\nNext step: discuss our current workflow, existing tools, and goals.`;document.querySelector('#brief-result').hidden=false;document.querySelector('#copy-status').textContent='';document.querySelector('#prepared-brief').focus();});
document.querySelector('#copy-button').addEventListener('click',async()=>{const field=document.querySelector('#prepared-brief');try{await navigator.clipboard.writeText(field.value);document.querySelector('#copy-status').textContent='Copied.';}catch{field.focus();field.select();document.querySelector('#copy-status').textContent='Select and copy the brief above.';}});

const demos={
 invoices:{mark:'IN',title:'From inbox to invoice.',subtitle:'One connected flow. No copy-and-paste.',steps:['Read the incoming document','Extract and check the details','Ready for your review'],action:'Approve sample invoice',done:'Sample invoice approved',message:'Example complete. A human reviews before anything is posted.'},
 onboarding:{mark:'HR',title:'A smoother first day.',subtitle:'The right tasks, routed to the right people.',steps:['Collect the onboarding details','Prepare the team checklist','Ready for your sign-off'],action:'Approve sample checklist',done:'Sample checklist approved',message:'Example complete. Tasks are organized in one shared workspace.'},
 reporting:{mark:'BI',title:'Reports without the scramble.',subtitle:'Bring the data together. Keep the insight.',steps:['Collect the source data','Prepare the weekly summary','Ready for your review'],action:'Review sample report',done:'Sample report reviewed',message:'Example complete. Your team reviews the summary before sharing.'}
};
let currentDemo='invoices';
function selectDemo(key){currentDemo=key;const d=demos[key];document.querySelectorAll('[data-demo]').forEach(b=>{const active=b.dataset.demo===key;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});document.querySelector('#demo-panel').setAttribute('aria-labelledby','tab-'+key);document.querySelector('.task-monogram').textContent=d.mark;document.querySelector('#demo-title').textContent=d.title;document.querySelector('#demo-subtitle').textContent=d.subtitle;['a','b','c'].forEach((suffix,i)=>document.querySelector('#demo-step-'+suffix).textContent=d.steps[i]);document.querySelector('#demo-run').textContent=d.action;document.querySelector('#demo-final-icon').textContent='';document.querySelector('#demo-final-icon').classList.remove('complete');document.querySelector('#demo-final-tag').textContent='YOU';document.querySelector('#demo-status').textContent='Try the example. No real data is processed.';}
document.querySelectorAll('[data-demo]').forEach((button,i,buttons)=>{button.addEventListener('click',()=>selectDemo(button.dataset.demo));button.addEventListener('keydown',e=>{let index;if(e.key==='ArrowRight')index=(i+1)%buttons.length;else if(e.key==='ArrowLeft')index=(i+buttons.length-1)%buttons.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=buttons.length-1;else return;e.preventDefault();selectDemo(buttons[index].dataset.demo);buttons[index].focus();});});
document.querySelector('#demo-run').addEventListener('click',()=>{const d=demos[currentDemo];document.querySelector('#demo-step-c').textContent=d.done;document.querySelector('#demo-final-icon').textContent='✓';document.querySelector('#demo-final-icon').classList.add('complete');document.querySelector('#demo-final-tag').textContent='DONE';document.querySelector('#demo-status').textContent=d.message;});
